-- public.worker_settle(p_world uuid, p_id integer)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.worker_settle(p_world uuid, p_id integer)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare c creature; d species_def; kind text; guard int := 0; done int := 0;
        spot record; stand record; step record; pace double precision; dist double precision;
        secs double precision; load jsonb; cx double precision; cy double precision;
        ax double precision; ay double precision; v_foe creature; v_corpse item;
        v_step record; v_site record; v_store record; v_in boolean;
        v_day int; v_held jsonb; v_left int; v_bed placed; v_sort record; v_spar creature; v_hive placed; v_trip record; v_made int[]; v_did jsonb; v_tire int; v_put jsonb; -- made log
        v_lv int; v_once int; v_routed boolean := true; -- storeys
        v_vine boolean := false; -- a bush picker planting vines
        v_hy_tried boolean := false; -- a hybrid that has looked for its second trade's work
begin
  select * into c from creature where world_id = p_world and id = p_id for update;
  if not found or c.mode <> 'deed' then return 0; end if;
  perform set_config('wildermon.around', '', true);
  -- Round a keeper who is offline: back where it came from (`around_end`).
  if c.around is not null and not keeper_awake(p_world, c.keeper) then
    perform around_end(p_world, p_id, 'Work around me stopped (offline)');
    return 0;
  end if;
  /*
   * Where it takes its orders from. A post stands in for a settlement, and a
   * worker with neither has nobody to take them from at all.
   */
  select * into v_site from work_site(p_world, c);
  if c.around is not null and v_site.x is not null then
    perform set_config('wildermon.around', jsonb_build_object('uid', c.keeper, 'x', v_site.x, 'y', v_site.y, 'r', v_site.radius)::text, true);
  end if;
  if v_site.x is null then
    /*
     * Let go, and told.
     *
     * A worker with neither a post nor a settlement to take orders from is
     * turned loose — which is right, because the cap on how many you may keep
     * is your settlement's level and it is nought without one. What was wrong
     * was doing it in silence. From the island: a wildermon that had been
     * working stood about on fifty tiles of forage it could have been on, and
     * nothing anywhere said it had stopped being a worker. The rules were
     * doing exactly as written and the only broken thing was that nobody was
     * told.
     */
    update creature set mode = 'wild', phase = 'idle', job = null, post = null
      where world_id = p_world and id = p_id;
    if c.keeper is not null then
      perform wtell(p_world, c.keeper,
        c.name || ': no settlement, returned to the wild.', 'event');
    end if;
    return 0;
  end if;
  select * into d from species_def where id = c.species;
  -- The trade it was set to, which is its species' own unless it was told otherwise.
  kind := coalesce(c.job, d.gathers);
  v_day := island_day(p_world);
  pace := d.speed * (age_row(c.born, old_of(c), age_pace(c))).speed * beast_mul(c, 'speed')
          * (1 + greatest(1, task_skill(c)) / 500);
  -- Its goes before it tires, as its blood makes them (`tire_of`).
  v_tire := tire_of(c);

  <<settle>>
  while c.until <= now() and guard < 120 loop
    guard := guard + 1;
    cx := c.to_x; cy := c.to_y;
    c.storey_from := c.storey;
    -- Along the way it was given (`worker_way_leg`): its next leg, and its phase kept for the end of the way.
    if c.way is not null then
      c := worker_way_next(p_world, c, cx, cy, c.until, pace);
      continue;
    end if;
    v_lv := null; v_routed := false;
    for v_once in 1..1 loop
    if d.hybrid_a is not null then
      if c.phase <> 'idle' or c.carrying is not null or c.fetching is not null then
        v_hy_tried := false;
      elsif not v_hy_tried and kind is distinct from d.trades[1] then
        kind := d.trades[1]; c.job := kind;
        update creature set job = kind where world_id = p_world and id = p_id;
      end if;
    end if;
    /*
     * A bush picker from `bush_vines_at()` on: on the vine planter's errand while it holds grape cuttings with a trellis
     * for them, or walks to the stores for them (`fetching`). Holding them with no trellis left, back to the stores.
     */
    v_vine := false;
    if kind = 'bush' and c.phase <> 'home' and stage_of(c) >= bush_vines_at() then
      if c.fetching = grape_cutting_item() and c.phase in ('out', 'work') then
        v_vine := true;
      elsif coalesce(c.carrying->>'def' = grape_cutting_item(), false) then
        v_vine := c.phase in ('out', 'work') or (vine_target(p_world, c, cx, cy)).id is not null;
        if not v_vine and c.phase = 'idle' then
          select * into v_store from worker_store(p_world, c, c.carrying->>'def', coalesce((c.carrying->>'count')::int, 1));
          if v_store.id is null then
            perform worker_nowhere(p_world, c); c.idle_what := null; c.idle_why := 'full'; c.idle_n := null;
            c.until := now() + interval '30 seconds';
            exit settle;
          end if;
          dist := sqrt((v_store.cx - cx) ^ 2 + (v_store.cy - cy) ^ 2);
          c.fetching := null;
          c.from_x := cx; c.from_y := cy; c.to_x := v_store.cx; c.to_y := v_store.cy;
          c.leg_at := c.until;
          c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
          c.until := c.leg_ends;
          c.phase := 'home';
          continue;
        end if;
      end if;
    end if;
    if kind = 'bush' and not v_vine and c.fetching is not null then c.fetching := null; end if;

    /*
     * Company first.
     *
     * Nothing works while something is coming at it, and the two trades that
     * fight for a living are always looking for company. A worker breaks off
     * between jobs rather than mid-load: what is already in its arms goes in
     * the crate before it goes for anything, which is the one place this is
     * tidier than the browser.
     */
    if c.phase = 'strike' then
      update creature set from_x = c.from_x, from_y = c.from_y, to_x = c.to_x, to_y = c.to_y,
          leg_at = c.leg_at, leg_ends = c.leg_ends, until = c.until, phase = c.phase,
          work_x = c.work_x, work_y = c.work_y, carrying = c.carrying, enemy = c.enemy,
          idle_why = c.idle_why, idle_what = c.idle_what, idle_n = c.idle_n, ledger = c.ledger, worn = c.worn, gear = c.gear, bed = c.bed,
          spar_with = c.spar_with, spar_at = c.spar_at, storey = c.storey, storey_from = c.storey_from, way = c.way, settled_at = now()
        where world_id = p_world and id = p_id;
      if c.enemy is not null and creature_attack(p_world, p_id, c.enemy) then done := done + 1; end if;
      select * into c from creature where world_id = p_world and id = p_id;
      c.phase := 'idle';
      c.leg_at := c.until; c.leg_ends := c.until;
      continue;

    elsif c.phase = 'stalk' then
      -- Arrived where the carcass went down. If somebody else has had it, the
      -- walk was wasted, which is what happens to a hunter now and then.
      c.carrying := take_from_ground(p_world, c.work_x, c.work_y, 'corpse');
      c.work_x := null; c.work_y := null;
      c.phase := 'idle';
      c.leg_at := c.until; c.leg_ends := c.until;
      c.until := c.until + interval '0.5 seconds';
      continue;
    end if;

    /*
     * Rest (`tire_goes`, `rest_for`). Up from a rest, its stamina full, and out of its bed. At a bed it walked to, into
     * it if it is still there and free, for `bed_rest` of the rest. And with no stamina left, idle with its arms empty
     * or between the steps of an errand: to the nearest free bed of its size on its settlement (`free_bed`), or a rest
     * where it stands. Nothing of a rest is a go.
     */
    if c.phase = 'rest' then
      update placed set sleeper = null where id = c.bed and sleeper = c.id;
      c.bed := null; c.worn := 0;
      c.idle_what := null; c.idle_why := null; c.idle_n := null;
      c.phase := 'idle';
      c.leg_at := c.until; c.leg_ends := c.until;
      continue;
    elsif c.phase = 'bed' then
      if exists (select 1 from placed b join furniture_def fd on fd.id = b.sub
                  where b.id = c.bed and b.world_id = p_world and b.sleeper is null and fd.den = den_class(c)
                    and c.post is null and c.around is null and on_home_deed(p_world, c.keeper, b.x, b.y)) then
        update placed set sleeper = c.id where id = c.bed;
        if c.keeper is not null and exists (select 1 from placed b where b.id = c.bed and b.made_by = c.keeper) then
          perform journal_once(p_world, c.keeper, 'bedded:own');
        end if;
        c.phase := 'rest'; c.idle_what := null; c.idle_why := 'rest'; c.idle_n := null;
        c.leg_at := c.until; c.leg_ends := c.until;
        c.until := c.until + make_interval(secs => rest_of(c) * bed_rest());
        continue;
      end if;
      -- Gone, or taken by another on the way: it looks again.
      c.bed := null;
      c.phase := 'idle';
      c.leg_at := c.until; c.leg_ends := c.until;
    end if;
    if c.phase = 'idle' and c.worn >= v_tire and (c.carrying is null or worker_errand(kind)) then
      c.spar_with := null;
      v_bed := free_bed(p_world, c, cx, cy);
      c.from_x := cx; c.from_y := cy; c.idle_n := null;
      if v_bed.id is not null then
        c.bed := v_bed.id;
        c.to_x := v_bed.cx; c.to_y := v_bed.cy;
        dist := sqrt((v_bed.cx - cx) ^ 2 + (v_bed.cy - cy) ^ 2);
        c.leg_at := c.until;
        c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
        c.until := c.leg_ends;
        c.phase := 'bed'; c.idle_what := null; c.idle_why := 'tired';
      else
        c.leg_at := c.until; c.leg_ends := c.until;
        c.until := c.until + make_interval(secs => rest_of(c));
        c.phase := 'rest'; c.idle_what := null; c.idle_why := 'rest';
      end if;
      continue;
    end if;

    /*
     * Off its ground: it walks back to it before anything else, a short leg at a time (`home_leg`), so that every leg
     * stays one a player beside it is told of.
     */
    if c.phase = 'idle' and greatest(abs(v_site.x + 0.5 - cx), abs(v_site.y + 0.5 - cy)) > v_site.radius + home_slack() then
      dist := sqrt((v_site.x + 0.5 - cx) ^ 2 + (v_site.y + 0.5 - cy) ^ 2);
      c.idle_what := null; c.idle_why := 'far'; c.idle_n := dist;
      select * into v_step from chase_leg(p_world, cx, cy,
        cx + (v_site.x + 0.5 - cx) * home_leg() / dist, cy + (v_site.y + 0.5 - cy) * home_leg() / dist);
      if v_step.x is null then
        c.from_x := cx; c.from_y := cy;
        c.leg_at := now(); c.leg_ends := now();
        c.until := now() + interval '4 seconds';
        exit settle;
      end if;
      c.from_x := cx; c.from_y := cy; c.to_x := v_step.x; c.to_y := v_step.y;
      c.leg_at := c.until;
      c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, sqrt((c.to_x - cx) ^ 2 + (c.to_y - cy) ^ 2) / greatest(0.1, pace)));
      c.until := c.leg_ends;
      continue;
    end if;

    if fight_trade(kind) and c.phase = 'idle' and c.carrying is not null then
      select * into v_store from worker_store(p_world, c, c.carrying->>'def', (c.carrying->>'count')::int);
      if v_store.id is null then
        c.idle_what := null; c.idle_why := 'full'; c.idle_n := null;
        c.until := now() + interval '30 seconds';
        exit settle;
      end if;
      ax := v_store.cx; ay := v_store.cy;
      dist := sqrt((ax - cx) ^ 2 + (ay - cy) ^ 2);
      c.from_x := cx; c.from_y := cy; c.to_x := ax; c.to_y := ay;
      c.leg_at := c.until;
      c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
      c.until := c.leg_ends;
      c.phase := 'home';
      continue;
    end if;

    /*
     * A spar with a Sparra of yours on the settlement (`sparGo`). It looks round for something wild on the settlement
     * as often as a guard does, and drops the spar at once for it; or for the Sparra gone, let it go or yielded. At the
     * end of the go, a blow each way (`spar_go`), and the second after a go, seen to strike.
     */
    if c.phase = 'spar' then
      select * into v_spar from creature where world_id = p_world and id = c.spar_with;
      v_foe := fight_target(p_world, p_id);
      if v_foe.id is not null or v_spar.id is null or v_spar.spar_with is distinct from p_id or v_spar.mode <> 'deed'
         or spar_yielded(v_spar) then
        c.phase := 'idle'; c.spar_with := null;
        c.leg_at := c.until; c.leg_ends := c.until;
        continue;
      elsif c.spar_at > c.until then
        c.until := least(c.spar_at, c.until + interval '1.5 seconds');
        continue;
      end if;
      update creature set from_x = c.from_x, from_y = c.from_y, to_x = c.to_x, to_y = c.to_y,
          leg_at = c.leg_at, leg_ends = c.leg_ends, until = c.until, phase = c.phase,
          idle_why = c.idle_why, idle_what = c.idle_what, idle_n = c.idle_n, idle_since = c.idle_since, ledger = c.ledger, worn = c.worn,
          enemy = c.enemy, spar_with = c.spar_with, spar_at = c.spar_at, storey = c.storey, storey_from = c.storey_from, way = c.way, settled_at = now()
        where world_id = p_world and id = p_id;
      perform spar_go(p_world, p_id, v_spar.id, c.until);
      select * into c from creature where world_id = p_world and id = p_id;
      done := done + 1;
      c.phase := 'strike';
      c.leg_at := c.until; c.leg_ends := c.until;
      c.until := c.until + interval '1 second';
      continue;
    end if;

    if c.phase = 'idle' and c.carrying is null
       and (fight_trade(kind) or c.enemy is not null or c.stance <> 'passive') then
      v_foe := fight_target(p_world, p_id);
      if v_foe.id is null then
        c.enemy := null;
      else
        if c.enemy is distinct from v_foe.id then
          -- It has just seen it. A guard trains its back by keeping watch; a
          -- hunter learns the country by hunting it.
          if fight_trade(kind) then
            perform worker_learn(p_world, p_id,
              case when kind = 'hunt' then 'fighting' else 'body_strength' end,
              case when kind = 'hunt' then 0.08 else 0.1 end);
          end if;
          c.enemy := v_foe.id;
        end if;
        ax := creature_x(v_foe); ay := creature_y(v_foe);
        dist := sqrt((ax - cx) ^ 2 + (ay - cy) ^ 2);
        if dist <= fight_reach(kind) then
          c.phase := 'strike';
          c.leg_at := c.until; c.leg_ends := c.until;
          c.until := c.until + make_interval(secs => fight_blow(kind) / beast_mul(c, 'haste'));
        else
          select * into v_step from chase_leg(p_world, cx, cy,
            cx + (ax - cx) * (dist - fight_reach(kind) / 2) / dist, cy + (ay - cy) * (dist - fight_reach(kind) / 2) / dist);
          if v_step.x is null then
            -- Nothing open at all: the browser gives up here too.
            c.enemy := null;
            c.until := c.until + interval '2 seconds';
          else
            c.from_x := cx; c.from_y := cy;
            c.to_x := v_step.x; c.to_y := v_step.y;
            c.leg_at := c.until;
            c.leg_ends := c.leg_at + make_interval(secs =>
              greatest(0.2, sqrt((c.to_x - cx) ^ 2 + (c.to_y - cy) ^ 2)
                            / greatest(0.1, pace * fight_pace(kind))));
            c.until := c.leg_ends;
          end if;
        end if;
        continue;
      end if;
    end if;

    /*
     * A guard a Sparra of yours on the settlement has picked (`sparGo`): to within `spar_reach` of it, and a go at its
     * task, its end in `spar_at`. Yielded, it stands until it has its breath back.
     */
    if kind = 'guard' and c.phase = 'idle' and c.carrying is null and c.post is null then
      select s.* into v_spar from creature s
       where s.world_id = p_world and s.spar_with = p_id and s.keeper = c.keeper and s.mode = 'deed'
       order by s.id limit 1;
      if v_spar.id is not null and v_spar.phase not in ('rest', 'bed') and not spar_yielded(v_spar) and not spar_yielded(c) then
        c.spar_with := v_spar.id;
        c.idle_what := null; c.idle_why := null; c.idle_n := null; c.idle_since := null;
        ax := creature_x(v_spar); ay := creature_y(v_spar);
        dist := sqrt((ax - cx) ^ 2 + (ay - cy) ^ 2);
        if dist > spar_reach() then
          select * into v_step from chase_leg(p_world, cx, cy,
            cx + (ax - cx) * (dist - spar_reach() / 2) / dist, cy + (ay - cy) * (dist - spar_reach() / 2) / dist);
          if v_step.x is null then
            c.spar_with := null;
            c.from_x := cx; c.from_y := cy;
            c.leg_at := c.until; c.leg_ends := c.until;
            c.until := c.until + interval '2 seconds';
            continue;
          end if;
          c.from_x := cx; c.from_y := cy; c.to_x := v_step.x; c.to_y := v_step.y;
          c.leg_at := c.until;
          c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, sqrt((c.to_x - cx) ^ 2 + (c.to_y - cy) ^ 2) / greatest(0.1, pace)));
          c.until := c.leg_ends;
          continue;
        end if;
        c.phase := 'spar';
        c.from_x := cx; c.from_y := cy; c.to_x := cx; c.to_y := cy;
        c.leg_at := c.until; c.leg_ends := c.until;
        c.spar_at := c.until + make_interval(secs => work_duration(task_skill(c)) / worker_pace(p_world, c, kind));
        c.until := least(c.spar_at, c.until + interval '1.5 seconds');
        continue;
      end if;
      c.spar_with := null;
      if c.idle_why = 'yielded' then
        if spar_yielded(c) then
          c.idle_n := spar_back(c);
          c.from_x := cx; c.from_y := cy; c.to_x := cx; c.to_y := cy;
          c.leg_at := now(); c.leg_ends := now();
          c.until := now() + interval '2 seconds';
          exit settle;
        end if;
        c.idle_what := null; c.idle_why := null; c.idle_n := null;
      end if;
    end if;

    /*
     * A Sparra on the settlement (`sparraStep`). Yielded, it stands until it has its breath back. Otherwise it keeps to
     * the guard it is sparring with while that one may, or picks the one whose turn it is, and stands for it to come,
     * looking again in a few seconds; with none, it says so and potters about the totem. Measured: a pick among two
     * guards about 8 ms, a guard's beat mid-spar about 4 ms, against about 40 ms for a guard's settle with nobody to
     * spar with.
     */
    if d.style = 'spar' and c.post is null and c.phase = 'idle' and c.carrying is null then
      if spar_yielded(c) then
        c.spar_with := null;
        c.idle_what := null; c.idle_why := 'yielded'; c.idle_n := spar_back(c);
        c.from_x := cx; c.from_y := cy; c.to_x := cx; c.to_y := cy;
        c.leg_at := now(); c.leg_ends := now();
        c.until := now() + interval '2 seconds';
        exit settle;
      end if;
      if c.idle_why = 'yielded' then c.idle_what := null; c.idle_why := null; c.idle_n := null; end if;
      if c.spar_with is not null then
        select * into v_spar from creature where world_id = p_world and id = c.spar_with;
        if v_spar.id is null or not spar_may(p_world, v_spar, c, v_site.x, v_site.y) then c.spar_with := null; end if;
      end if;
      if c.spar_with is null then
        select g.* into v_spar from creature g
         where g.world_id = p_world and g.keeper = c.keeper and g.mode = 'deed' and g.post is null
           and spar_may(p_world, g, c, v_site.x, v_site.y)
         order by g.spar_at nulls first, g.id
         limit 1;
        c.spar_with := v_spar.id;
      end if;
      c.from_x := cx; c.from_y := cy;
      if c.spar_with is not null then
        -- Its guard's go sets it going again when it ends (`spar_go`); this only notices a guard called away in between.
        c.idle_what := null; c.idle_why := null; c.idle_n := null; c.idle_since := null;
        c.to_x := cx; c.to_y := cy;
        c.leg_at := now(); c.leg_ends := now();
        c.until := now() + interval '5 seconds';
        exit settle;
      end if;
      c.idle_what := null; c.idle_why := 'nospar'; c.idle_n := null;
      c.idle_since := coalesce(c.idle_since, now());
      c.to_x := v_site.x + 0.5 + (hash_tile(p_id, guard, 601) * 2 - 1) * 3;
      c.to_y := v_site.y + 0.5 + (hash_tile(p_id, guard, 701) * 2 - 1) * 3;
      if not creature_tile_ok(p_world, floor(c.to_x)::int, floor(c.to_y)::int) then
        c.to_x := cx; c.to_y := cy;
      end if;
      c.leg_at := now();
      c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, sqrt((c.to_x - cx) ^ 2 + (c.to_y - cy) ^ 2) / greatest(0.1, pace)));
      c.until := c.leg_ends + worker_rest(c.idle_since) * beast_mul(c, 'idle');
      exit settle;
    end if;

    if kind = 'hunt' and c.phase = 'idle' and c.carrying is null then
      if c.work_x is not null and not exists (select 1 from item i
           where i.world_id = p_world and i.holder = 'ground'
             and i.gx = c.work_x and i.gy = c.work_y and i.def = 'corpse') then
        c.work_x := null; c.work_y := null;
      end if;
      if c.work_x is null then
        v_corpse := carcass_near(p_world, v_site.x, v_site.y, v_site.radius, cx, cy);
        if v_corpse.id is not null then c.work_x := v_corpse.gx; c.work_y := v_corpse.gy; end if;
      end if;
      if c.work_x is not null then
        ax := c.work_x + 0.5; ay := c.work_y + 0.5;
        dist := sqrt((ax - cx) ^ 2 + (ay - cy) ^ 2);
        c.from_x := cx; c.from_y := cy; c.to_x := ax; c.to_y := ay;
        c.leg_at := c.until;
        c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
        c.until := c.leg_ends;
        c.phase := 'stalk';
        continue;
      end if;
    end if;

    if c.around is not null and c.phase = 'idle' and c.carrying is null
       and not exists (select 1 from around_stores(p_world, c.keeper, v_site.x, v_site.y, v_site.radius)) then
      c.from_x := cx; c.from_y := cy; c.to_x := cx; c.to_y := cy;
      c.idle_what := null; c.idle_why := 'nostore'; c.idle_n := v_site.radius;
      c.leg_at := now(); c.leg_ends := now();
      c.until := now() + interval '4 seconds';
      -- Off its ground, it wanders back in round its keeper while it waits, as an errand with nothing to run does.
      if greatest(abs(v_site.x + 0.5 - cx), abs(v_site.y + 0.5 - cy)) > v_site.radius then
        c.to_x := v_site.x + 0.5 + (hash_tile(p_id, guard, 601) * 2 - 1) * 3;
        c.to_y := v_site.y + 0.5 + (hash_tile(p_id, guard, 701) * 2 - 1) * 3;
        if not creature_tile_ok(p_world, floor(c.to_x)::int, floor(c.to_y)::int) then
          c.to_x := cx; c.to_y := cy;
        end if;
        c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, sqrt((c.to_x - cx) ^ 2 + (c.to_y - cy) ^ 2) / greatest(0.1, pace)));
        c.until := c.leg_ends + interval '4 seconds';
      end if;
      exit settle;
    end if;

    if worker_errand(kind) or v_vine then
      -- Everything an errand asks about is on the row, so the row goes down
      -- before it is asked.
      update creature set from_x = c.from_x, from_y = c.from_y, to_x = c.to_x, to_y = c.to_y,
          leg_at = c.leg_at, leg_ends = c.leg_ends, until = c.until, phase = c.phase,
          work_x = c.work_x, work_y = c.work_y, carrying = c.carrying, fetching = c.fetching,
          idle_why = c.idle_why, idle_what = c.idle_what, idle_n = c.idle_n, ledger = c.ledger, worn = c.worn, gear = c.gear, bed = c.bed, storey = c.storey, storey_from = c.storey_from, way = c.way, settled_at = now()
        where world_id = p_world and id = p_id;

      if c.phase = 'fetch' then
        -- Its stage's loads of it, as many as the errand wants (`errand_fetch_n`).
        load := take_some_stored(p_world, c.keeper, array[c.fetching], errand_fetch_n(p_world, c), c.work_x, c.work_y);
        if load is null then
          c.idle_what := null; c.idle_why := 'stock'; c.idle_n := null;
          c.phase := 'idle';
          c.leg_at := c.until; c.leg_ends := c.until;
          c.until := now() + interval '4 seconds';
          exit settle;
        end if;
        c.carrying := load;
        c.fetching := null;
        c.phase := 'idle';
        c.leg_at := c.until; c.leg_ends := c.until;
        c.until := c.until + interval '0.5 seconds';

      elsif c.phase = 'out' then
        c.phase := 'work';
        c.leg_at := c.until; c.leg_ends := c.until;
        c.until := c.until + make_interval(secs => work_duration(task_skill(c)) / worker_pace(p_world, c, kind));

      elsif c.phase = 'work' then
        v_held := c.carrying;
        if private.errand_go_made(p_world, p_id, case when v_vine then 'vine' end) then
          done := done + 1;
          v_put := private.worker_made_take();
          select * into c from creature where world_id = p_world and id = p_id;
          v_left := case when c.carrying->>'def' = v_held->>'def' then coalesce((c.carrying->>'count')::int, 1) else 0 end;
          c.ledger := ledger_add(c.ledger, v_day, 1, 0, v_held->>'def',
                                 greatest(0, coalesce((v_held->>'count')::int, 1) - v_left));
          v_did := did_add(v_did, 'handled', v_held->>'def', greatest(0, coalesce((v_held->>'count')::int, 1) - v_left));
          -- And what it put into the stores as its work (`worker_put`): made in place.
          c.ledger := private.ledger_add_made(c.ledger, v_day, v_put);
          v_did := private.did_add_made(v_did, v_put);
          c.worn := c.worn + 1;
      if c.gear is not null and pack_loads_of(c) > 0 then c.gear := gear_wear(p_world, c, 'pack', 1); end if;
          c.idle_what := null; c.idle_why := null; c.idle_n := null;
        else
          select * into c from creature where world_id = p_world and id = p_id;
        end if;
        c.phase := 'idle';
        c.leg_at := c.until; c.leg_ends := c.until;
        c.until := c.until + interval '1 second';

      else
        select * into step from errand_step(p_world, p_id, case when v_vine then 'vine' end);
        if step.gx is null then
          if d.hybrid_a is not null and not v_hy_tried and c.carrying is null and not v_vine then
            v_hy_tried := true;
            kind := case when kind = d.trades[1] then d.trades[2] else d.trades[1] end; c.job := kind;
            update creature set job = kind where world_id = p_world and id = p_id;
            continue;
          end if;
          -- Nothing to run. Replaying an afternoon of that produces nothing.
          c.from_x := cx; c.from_y := cy;
          c.idle_what := step.why_what; c.idle_why := step.why; c.idle_n := step.why_n;
          -- Off its ground, it wanders back in round the token while it waits, as a trade with nothing to gather does.
          if greatest(abs(v_site.x + 0.5 - cx), abs(v_site.y + 0.5 - cy)) > v_site.radius then
            c.to_x := v_site.x + 0.5 + (hash_tile(p_id, guard, 601) * 2 - 1) * 3;
            c.to_y := v_site.y + 0.5 + (hash_tile(p_id, guard, 701) * 2 - 1) * 3;
            if not creature_tile_ok(p_world, floor(c.to_x)::int, floor(c.to_y)::int) then
              c.to_x := cx; c.to_y := cy;
            end if;
            c.leg_at := now();
            c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, sqrt((c.to_x - cx) ^ 2 + (c.to_y - cy) ^ 2) / greatest(0.1, pace)));
            c.until := c.leg_ends + interval '4 seconds';
            exit settle;
          end if;
          c.leg_at := now(); c.leg_ends := now();
          c.until := now() + interval '4 seconds';
          exit settle;
        end if;
        c.work_x := step.wx; c.work_y := step.wy;
        c.idle_what := null; c.idle_why := null; c.idle_n := null;
        c.fetching := step.want;
        v_lv := step.gl;
        dist := sqrt((step.gx - cx) ^ 2 + (step.gy - cy) ^ 2);
        c.from_x := cx; c.from_y := cy; c.to_x := step.gx; c.to_y := step.gy;
        c.leg_at := c.until;
        c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
        c.until := c.leg_ends;
        c.phase := case when step.want is null then 'out' else 'fetch' end;
      end if;
      continue;
    end if;

    if c.phase = 'out' then
      c.phase := 'work';
      c.leg_at := c.until; c.leg_ends := c.until;
      c.until := c.until + make_interval(secs => work_duration(task_skill(c)) / worker_pace(p_world, c, kind));

    elsif c.phase = 'work' then
      -- A Vesp at a flower: the moment it set off from its hive, the go's start less its flight out (`tripAt`).
      if kind = 'hive' then
        secs := extract(epoch from c.leg_at) - greatest(0.2, sqrt((cx - c.from_x) ^ 2 + (cy - c.from_y) ^ 2) / greatest(0.1, pace));
      end if;
      update creature set from_x = cx, from_y = cy, to_x = cx, to_y = cy,
          leg_at = c.leg_at, leg_ends = c.leg_ends, until = c.until, phase = c.phase,
          work_x = c.work_x, work_y = c.work_y, idle_why = c.idle_why, idle_what = c.idle_what, idle_n = c.idle_n, ledger = c.ledger, worn = c.worn, gear = c.gear, bed = c.bed,
          carrying = c.carrying, storey = c.storey, storey_from = c.storey_from, way = c.way, settled_at = now()
        where world_id = p_world and id = p_id;
      load := worker_do(p_world, p_id);
      select * into c from creature where world_id = p_world and id = p_id;
      -- And its line's own third-stage more of it (`perk_more`).
      load := perk_more(c, load);
      done := done + 1;
      c.ledger := ledger_add(c.ledger, v_day, 1, 0, null, 0);
      c.worn := c.worn + 1;
      if c.gear is not null and pack_loads_of(c) > 0 then c.gear := gear_wear(p_world, c, 'pack', 1); end if;
      c.idle_what := null; c.idle_why := null; c.idle_n := null;
      -- A Vesp flies back to its hive with what it gathered, and when it set off; its hive gone, that is lost.
      if kind = 'hive' then
        select * into v_hive from placed h where h.world_id = p_world and h.kind = 'furniture' and h.sub = 'hive'
           and h.x = c.work_x and h.y = c.work_y and h.crumbles_at is null order by h.id limit 1;
        if load is null or v_hive.id is null then
          c.carrying := null;
          c.phase := 'idle';
          c.leg_at := c.until; c.leg_ends := c.until;
          c.until := c.until + make_interval(secs => vesp_rest());
        else
          c.carrying := load || jsonb_build_object('since', secs);
          dist := sqrt((v_hive.cx - cx) ^ 2 + (v_hive.cy - cy) ^ 2);
          c.from_x := cx; c.from_y := cy; c.to_x := v_hive.cx; c.to_y := v_hive.cy;
          c.leg_at := c.until;
          c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
          c.until := c.leg_ends;
          c.phase := 'home';
        end if;
        continue;
      end if;
      -- Into its arms with what it has gathered already this trip; and with room in them for another of its stage's
      -- loads (`stage_loads`), out to the next tile rather than home.
      c.carrying := load_join(c.carrying, load);
      c.work_x := null; c.work_y := null;
      if load is null or (load_trade(kind) and loads_in(c.carrying) < stage_loads(c)) then
        c.phase := 'idle';
        c.leg_at := c.until; c.leg_ends := c.until;
        c.until := c.until + interval '1 second';
      else
        select * into v_store from worker_store(p_world, c, c.carrying->>'def', (c.carrying->>'count')::int);
        if v_store.id is null then
          -- Everything on the deed is full. A worker will not tip a load out
          -- on the ground: it holds it and waits for room, and says so, once
          -- in a while rather than once a job.
          perform worker_nowhere(p_world, c); c.idle_what := null; c.idle_why := 'full'; c.idle_n := null;
          c.phase := 'idle';
          c.leg_at := c.until; c.leg_ends := c.until;
          c.until := now() + interval '30 seconds';
          exit settle;
        end if;
        ax := v_store.cx; ay := v_store.cy;
        dist := sqrt((ax - cx) ^ 2 + (ay - cy) ^ 2);
        secs := greatest(0.2, dist / greatest(0.1, pace));
        c.from_x := cx; c.from_y := cy; c.to_x := ax; c.to_y := ay;
        c.leg_at := c.until; c.leg_ends := c.leg_at + make_interval(secs => secs);
        c.until := c.leg_ends;
        c.phase := 'home';
      end if;

    elsif c.phase = 'home' and kind = 'hive' then
      /*
       * A Vesp at its hive with what it gathered (`vespHome`): as much honey as a skep there would have made from
       * when it set off to when it sets off again, `vesp_rest` after this, into the hive (`vesp_put`); the whole
       * honey and beeswax that made, on its ledger. Its hive gone, what it gathered is lost.
       */
      select * into v_hive from placed h where h.world_id = p_world and h.kind = 'furniture' and h.sub = 'hive'
         and h.x = c.work_x and h.y = c.work_y and h.crumbles_at is null order by h.id limit 1;
      if v_hive.id is not null and c.carrying ? 'since' then
        if sqrt((v_hive.cx - cx) ^ 2 + (v_hive.cy - cy) ^ 2) > 1.6 then
          dist := sqrt((v_hive.cx - cx) ^ 2 + (v_hive.cy - cy) ^ 2);
          c.from_x := cx; c.from_y := cy; c.to_x := v_hive.cx; c.to_y := v_hive.cy;
          c.leg_at := c.until;
          c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
          c.until := c.leg_ends;
          continue;
        end if;
        v_made := vesp_put(p_world, v_hive.id,
          vesp_honey(skep_flowers(p_world, v_hive.x, v_hive.y, c.until), season_at(c.until),
                     extract(epoch from c.until) - (c.carrying->>'since')::double precision + vesp_rest()),
          (c.carrying->>'ql')::double precision);
        if v_made[1] > 0 then
          perform away_count(p_world, c.keeper, 'haul', 'honey', v_made[1]::bigint);
          c.ledger := ledger_add(c.ledger, v_day, 0, 0, 'honey', v_made[1]); v_did := did_add(v_did, 'stored', 'honey', v_made[1]);
        end if;
        if v_made[2] > 0 then
          perform away_count(p_world, c.keeper, 'haul', 'wax', v_made[2]::bigint);
          c.ledger := ledger_add(c.ledger, v_day, 0, 0, 'wax', v_made[2]); v_did := did_add(v_did, 'stored', 'wax', v_made[2]);
        end if;
      end if;
      c.carrying := null;
      c.phase := 'idle';
      c.leg_at := c.until; c.leg_ends := c.until;
      c.until := c.until + make_interval(secs => vesp_rest());

    elsif c.phase = 'home' then
      /*
       * Wherever the room is *now*. A crate that had room when the walk began
       * may be full by the time the load arrives — somebody else filled it, or
       * another worker got there first — and the old rule walked to the
       * settlement's crate, failed quietly into a full one and carried the
       * load back out to the fields. Reported as workers overdelivering to a
       * full crate with an empty one standing beside it.
       */
      if c.carrying is not null then
        select * into v_store from worker_store(p_world, c, c.carrying->>'def', (c.carrying->>'count')::int);
        if v_store.id is null then
          perform worker_nowhere(p_world, c); c.idle_what := null; c.idle_why := 'full'; c.idle_n := null;
          c.until := now() + interval '30 seconds';
          c.phase := 'idle';
          c.leg_at := c.until; c.leg_ends := c.until;
          exit settle;
        end if;
        if sqrt((v_store.cx - cx) ^ 2 + (v_store.cy - cy) ^ 2) > 1.6 then
          -- The room is somewhere else now: walk there rather than stand at a
          -- full crate holding a load.
          dist := sqrt((v_store.cx - cx) ^ 2 + (v_store.cy - cy) ^ 2);
          c.from_x := cx; c.from_y := cy; c.to_x := v_store.cx; c.to_y := v_store.cy;
          c.leg_at := c.until;
          c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
          c.until := c.leg_ends;
          continue;
        end if;
        if v_store.kind = 'crate' then
          v_in := crate_add(p_world, v_store.id::int, c.carrying->>'def',
            (c.carrying->>'count')::int, (c.carrying->>'ql')::double precision, c.carrying->>'extra');
        else
          v_in := furniture_add(p_world, v_store.id, c.carrying->>'def',
            (c.carrying->>'count')::int, (c.carrying->>'ql')::double precision, c.carrying->>'extra');
        end if;
        if v_in then
          -- Counted for its keeper, if they are away: what came home while they were gone.
          perform away_count(p_world, c.keeper, 'haul', c.carrying->>'def', (c.carrying->>'count')::bigint);
          c.ledger := ledger_add(c.ledger, v_day, 0, 0, c.carrying->>'def', coalesce((c.carrying->>'count')::int, 1));
          v_did := did_add(v_did, 'stored', c.carrying->>'def', coalesce((c.carrying->>'count')::int, 1));
          -- And the next load of the trip, put away the same way, until its arms are empty.
          c.carrying := load_next(c.carrying);
          if c.carrying is not null then continue; end if;
        end if;
      end if;
      c.phase := 'idle';
      c.leg_at := c.until; c.leg_ends := c.until;
      c.until := c.until + interval '1 second';

    else
      -- The fields' growth brought up to date once for the whole of the ground
      -- it works, rather than a tile at a time inside the search.
      if kind = 'farm' then
        perform crops_settle(p_world, v_site.x + 0.5, v_site.y + 0.5, v_site.radius);
      end if;
      -- A Vesp: out from the nearest hive in its range with room to the next flower in reach of it, or why not
      -- (`vesp_trip`). Nothing to do is said, an hour of no hive is told, and it waits, as any worker with none.
      if kind = 'hive' then
        select * into v_trip from vesp_trip(p_world, cx, cy, v_site.x, v_site.y, v_site.radius,
          coalesce((ledger_roll(c.ledger, v_day)->'now'->>'goes')::int, 0), c.until);
        if v_trip.why is null then
          c.work_x := v_trip.hx; c.work_y := v_trip.hy;
          c.idle_since := null; c.idle_what := null; c.idle_why := null; c.idle_n := null;
          ax := v_trip.fx + 0.5; ay := v_trip.fy + 0.5;
          dist := sqrt((ax - cx) ^ 2 + (ay - cy) ^ 2);
          c.from_x := cx; c.from_y := cy; c.to_x := ax; c.to_y := ay;
          c.leg_at := c.until;
          c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
          c.until := c.leg_ends;
          c.phase := 'out';
          continue;
        end if;
        c.idle_since := coalesce(c.idle_since, now()); c.idle_what := null; c.idle_why := v_trip.why; c.idle_n := v_trip.n;
        if v_trip.why = 'range' then
          perform worker_idle(p_world, c, kind, v_site.x, v_site.y, v_site.radius, v_site.post);
        end if;
        c.from_x := cx; c.from_y := cy;
        c.to_x := v_site.x + 0.5 + (hash_tile(p_id, guard, 601) * 2 - 1) * 3;
        c.to_y := v_site.y + 0.5 + (hash_tile(p_id, guard, 701) * 2 - 1) * 3;
        if not creature_tile_ok(p_world, floor(c.to_x)::int, floor(c.to_y)::int) then
          c.to_x := cx; c.to_y := cy;
        end if;
        dist := sqrt((c.to_x - cx) ^ 2 + (c.to_y - cy) ^ 2);
        c.leg_at := now();
        c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
        c.until := c.leg_ends + worker_rest(c.idle_since) * beast_mul(c, 'idle');
        exit settle;
      end if;
      select * into spot from find_work_tile(p_world, v_site.x, v_site.y, v_site.radius, kind, c);
      if spot.x is null and kind = 'fetch' and v_site.post is null and c.around is null then
        select * into v_sort from sort_stack(p_world, c, cx, cy);
        if v_sort.iid is not null then
          c.work_x := v_sort.x; c.work_y := v_sort.y;
          c.idle_since := null; c.idle_what := null; c.idle_why := null; c.idle_n := null;
          dist := sqrt((v_sort.cx - cx) ^ 2 + (v_sort.cy - cy) ^ 2);
          c.from_x := cx; c.from_y := cy; c.to_x := v_sort.cx; c.to_y := v_sort.cy;
          c.leg_at := c.until;
          c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
          c.until := c.leg_ends;
          c.phase := 'out';
          continue;
        end if;
      end if;
      if spot.x is null and kind = 'bush' and c.carrying is null and stage_of(c) >= bush_vines_at() then
        -- Everything the errand asks about is on the row, so the row goes down before it is asked.
        update creature set from_x = c.from_x, from_y = c.from_y, to_x = c.to_x, to_y = c.to_y, carrying = c.carrying,
            storey = c.storey
          where world_id = p_world and id = p_id;
        select * into step from errand_step(p_world, p_id, 'vine');
        if step.gx is not null then
          c.work_x := step.wx; c.work_y := step.wy;
          c.idle_since := null; c.idle_what := null; c.idle_why := null; c.idle_n := null;
          c.fetching := coalesce(step.want, grape_cutting_item());
          v_lv := step.gl;
          dist := sqrt((step.gx - cx) ^ 2 + (step.gy - cy) ^ 2);
          c.from_x := cx; c.from_y := cy; c.to_x := step.gx; c.to_y := step.gy;
          c.leg_at := c.until;
          c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
          c.until := c.leg_ends;
          c.phase := 'out';
          continue;
        end if;
      end if;
      if spot.x is null and c.carrying is not null then
        -- Nothing more to be had, and loads in its arms: home with what it has.
        select * into v_store from worker_store(p_world, c, c.carrying->>'def', (c.carrying->>'count')::int);
        if v_store.id is not null then
          dist := sqrt((v_store.cx - cx) ^ 2 + (v_store.cy - cy) ^ 2);
          c.from_x := cx; c.from_y := cy; c.to_x := v_store.cx; c.to_y := v_store.cy;
          c.leg_at := c.until;
          c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
          c.until := c.leg_ends;
          c.phase := 'home';
          continue;
        end if;
      end if;
      if spot.x is null and d.hybrid_a is not null and not v_hy_tried and c.carrying is null then
        v_hy_tried := true;
        kind := case when kind = d.trades[1] then d.trades[2] else d.trades[1] end; c.job := kind;
        update creature set job = kind where world_id = p_world and id = p_id;
        continue;
      end if;
      if spot.x is null then
        -- Nothing of its trade anywhere it can reach. It wanders a few tiles
        -- and waits, which from outside is a beast standing about for no
        -- reason anybody is ever told. The clock on it starts here; whether
        -- that is worth a word is `worker_idle`'s to decide, and it wants an
        -- hour of it before it says anything, so that a trade which has run
        -- dry for the day is not mistaken for one that is stuck.
        c.idle_since := coalesce(c.idle_since, now()); c.idle_what := null; c.idle_why := 'range'; c.idle_n := v_site.radius;
        -- All of it in reach worked and on its wait: the seconds till the soonest is back (`worker_wait_left`).
        if worker_wait_left(p_world, v_site.x, v_site.y, v_site.radius, kind) is not null then
          c.idle_why := 'waiting'; c.idle_n := ceil(worker_wait_left(p_world, v_site.x, v_site.y, v_site.radius, kind));
        else
          -- Nothing coming back: an hour of it is worth a word (`worker_idle`); a wait is not.
          perform worker_idle(p_world, c, kind, v_site.x, v_site.y, v_site.radius, v_site.post);
        end if;
        c.from_x := cx; c.from_y := cy;
        c.to_x := v_site.x + 0.5 + (hash_tile(p_id, guard, 601) * 2 - 1) * 3;
        c.to_y := v_site.y + 0.5 + (hash_tile(p_id, guard, 701) * 2 - 1) * 3;
        if not creature_tile_ok(p_world, floor(c.to_x)::int, floor(c.to_y)::int) then
          c.to_x := cx; c.to_y := cy;
        end if;
        dist := sqrt((c.to_x - cx) ^ 2 + (c.to_y - cy) ^ 2);
        c.leg_at := now();
        c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
        c.until := c.leg_ends + worker_rest(c.idle_since) * beast_mul(c, 'idle');
        exit settle;
      else
        -- Worked from the bank when there is no standing on it: always for a
        -- tree, a rod or a fruit bough, and for a rock face when the water
        -- over it is deeper than a beast can wade.
        if kind in ('woodcut', 'prune', 'fish', 'fruit', 'sprout', 'resin')
           or (kind in ('mine', 'quarry') and not creature_tile_ok(p_world, spot.x, spot.y)) then
          select * into stand from beside_tile(p_world, spot.x, spot.y);
          if stand.x is null then
            /*
             * A tile of its trade with nowhere to stand and work it from.
             *
             * This added four seconds and went round again, and round again
             * re-derived the very same tile: `find_work_tile` walks the rings
             * outward from the site and hands back the first thing that
             * passes, so nothing about waiting changes which tile that is.
             * The only thing that could is the ground itself. A beast in here
             * stands still for ever and says nothing, which is the shape of
             * every bad hour this island has had lately.
             *
             * It is unreachable today, and that is worth being plain about:
             * `worker_gatherable` demands `face_reach`, and `face_reach` only
             * passes without standing room when `beside_tile` has something in
             * it, so the two cannot presently disagree. This is written as a
             * refusal rather than a retry so that the next rule added to one
             * of them and not the other is a worker that goes quiet and gets
             * reported, not one that spins in silence.
             *
             * Having found a tile it cannot work is having found nothing, so
             * it leaves by the same door: the idle clock starts, and an hour
             * of it is a word to the keeper.
             */
            c.idle_since := coalesce(c.idle_since, now()); c.idle_what := null; c.idle_why := 'range'; c.idle_n := v_site.radius;
            perform worker_idle(p_world, c, kind, v_site.x, v_site.y, v_site.radius, v_site.post);
            c.from_x := cx; c.from_y := cy;
            c.leg_at := now(); c.leg_ends := now();
            c.until := now() + worker_rest(c.idle_since) * beast_mul(c, 'idle');
            exit settle;
          end if;
          ax := stand.x + 0.5; ay := stand.y + 0.5;
        else
          ax := spot.x + 0.5; ay := spot.y + 0.5;
        end if;
        c.work_x := spot.x; c.work_y := spot.y;
        if kind = 'farm' then v_lv := farm_work_level(p_world, spot.x, spot.y); end if;
        -- Anything found at all, and the idle clock starts over.
        c.idle_since := null;
        c.idle_what := null; c.idle_why := null; c.idle_n := null;
        dist := sqrt((ax - cx) ^ 2 + (ay - cy) ^ 2);
        c.from_x := cx; c.from_y := cy; c.to_x := ax; c.to_y := ay;
        c.leg_at := c.until;
        c.leg_ends := c.leg_at + make_interval(secs => greatest(0.2, dist / greatest(0.1, pace)));
        c.until := c.leg_ends;
        c.phase := 'out';
      end if;
    end if;
    end loop;
    -- A leg made this pass, to or from a storey by the stairs (`worker_way_leg`).
    if c.to_x is distinct from cx or c.to_y is distinct from cy then c := worker_way_leg(p_world, c, cx, cy, pace, v_lv); end if;
    v_routed := true;
  end loop;
  -- And one made on the way out of the loop.
  if not v_routed and (c.to_x is distinct from cx or c.to_y is distinct from cy) then
    c := worker_way_leg(p_world, c, cx, cy, pace, v_lv);
  end if;

  if c.until <= now() then
    c.from_x := c.to_x; c.from_y := c.to_y; c.storey_from := c.storey;
    c.leg_at := now(); c.leg_ends := now(); c.until := now() + interval '1 second';
  end if;

  update creature set from_x = c.from_x, from_y = c.from_y, to_x = c.to_x, to_y = c.to_y,
      leg_at = c.leg_at, leg_ends = c.leg_ends, until = c.until, phase = c.phase,
      work_x = c.work_x, work_y = c.work_y, carrying = c.carrying, fetching = c.fetching,
      idle_since = c.idle_since, idle_why = c.idle_why, idle_what = c.idle_what, idle_n = c.idle_n, ledger = c.ledger, worn = c.worn, gear = c.gear, bed = c.bed,
      enemy = c.enemy, spar_with = c.spar_with, spar_at = c.spar_at, storey = c.storey, storey_from = c.storey_from, way = c.way, settled_at = now()
    where world_id = p_world and id = p_id
      -- Only when it changes the row (`creature_storey` asked of one upstairs or on a staircase, which may).
      and (coalesce(c.storey <> 0 or c.storey_from <> 0 or c.way is not null, false)
           or (from_x, from_y, to_x, to_y, leg_at, leg_ends, until, phase, work_x, work_y, carrying, fetching,
               idle_since, idle_why, idle_what, idle_n, ledger, worn, gear, bed, enemy, spar_with, spar_at,
               storey, storey_from, way, settled_at)
              is distinct from
              (c.from_x, c.from_y, c.to_x, c.to_y, c.leg_at, c.leg_ends, c.until, c.phase, c.work_x, c.work_y, c.carrying, c.fetching,
               c.idle_since, c.idle_why, c.idle_what, c.idle_n, c.ledger, c.worn, c.gear, c.bed, c.enemy, c.spar_with, c.spar_at,
               c.storey, c.storey_from, c.way, now()));
  if v_did is not null and c.keeper is not null then perform wtell(p_world, c.keeper, work_done_line(c.name, v_did)); end if;
  perform set_config('wildermon.around', '', true);
  return done;
end $function$
